import type {Room} from '@/lib/pilot';
import type {ReportCell} from '@/lib/report-export';

export type MaintenanceInterval={closure_id:string;start:string;end:string;end_exclusive:true};
export type MaintenanceRoom=Room&{maintenance_intervals?:MaintenanceInterval[]};
export type RoomClosure={id:string;room_id:string;room_type_id:string;room_label:string;room_state_version:number;scheduled_start:string;scheduled_end:string;effective_end:string;reason:string;created_at:string;created_by:string;created_time_zone:string;released_at:string|null;released_by:string|null;release_reason:string|null;status:'scheduled'|'active'|'ended'|'released';occupied_reservation_id:string|null;occupancy_conflict:boolean};
export type MaintenanceInventory={stay_date:string;room_type_id:string;room_type_name:string;configured_units:number|null;physical_units:number;closed_units:number;effective_units:number|null;reserved_units:number;available_units:number|null;shortfall_units:number|null};
export type MaintenanceData={property_id:string;time_zone:string;business_date:string;role:string;can_manage:boolean;generated_at:string;period:{start:string;end:string;end_exclusive:true};closures:RoomClosure[];inventory:MaintenanceInventory[];definitions:unknown};
type Expected={p_request:string;p_expected_room_version:number;p_expected_business_date:string;p_reason:string};
export type CreateClosureCommand=Expected&{p_room:string;p_start:string;p_end:string};
export type ReleaseClosureCommand=Expected&{p_closure:string};
type Scope={actor:string;tenant:string;property:string};
type Review={room_id:string;room_label:string;scheduled_start:string;scheduled_end:string};
export type PendingMaintenance=Scope&{review:Review}&({action:'create_room_closure';command:CreateClosureCommand}|{action:'release_room_closure';command:ReleaseClosureCommand});
export type MaintenanceResult={tenant_id:string;property_id:string;request_id:string;action:'create_room_closure'|'release_room_closure';closure:RoomClosure;room_id:string;room_state_version:number;business_date:string;housekeeping_changed:false;financial_changed:false;configured_capacity_changed:false;replayed:boolean};
export type MaintenanceStatus={found:boolean;action?:string;result?:MaintenanceResult};

const uuid=(value:unknown):value is string=>typeof value==='string'&&/^[a-f0-9]{8}(-[a-f0-9]{4}){3}-[a-f0-9]{12}$/i.test(value);
const object=(value:unknown):value is Record<string,unknown>=>!!value&&typeof value==='object'&&!Array.isArray(value);
const version=(value:unknown)=>Number.isSafeInteger(value)&&Number(value)>0;
const count=(value:unknown)=>Number.isSafeInteger(value)&&Number(value)>=0;
const timestamp=(value:unknown)=>typeof value==='string'&&Number.isFinite(Date.parse(value));
const exactKeys=(value:object,keys:string[])=>Object.keys(value).sort().join(',')===[...keys].sort().join(',');
export const maintenanceKey=(actor:string,tenant:string,property:string)=>'iratepilot-pms-pending-maintenance:'+actor+':'+tenant+':'+property;
export function validMaintenanceDate(value:unknown):value is string{return typeof value==='string'&&/^[1-9]\d{3}-\d{2}-\d{2}$/.test(value)&&Number.isFinite(Date.parse(value+'T00:00:00Z'))&&new Date(value+'T00:00:00Z').toISOString().slice(0,10)===value}
export function addMaintenanceDays(date:string,days:number){if(!validMaintenanceDate(date)||!Number.isSafeInteger(days))throw Error('A valid property business date is required.');const value=new Date(date+'T00:00:00Z');value.setUTCDate(value.getUTCDate()+days);const result=value.toISOString().slice(0,10);if(!validMaintenanceDate(result))throw Error('The maintenance date is outside the supported range.');return result}
export function maintenanceNights(start:string,end:string){return validMaintenanceDate(start)&&validMaintenanceDate(end)?(Date.parse(end+'T00:00:00Z')-Date.parse(start+'T00:00:00Z'))/86400000:NaN}
export function validMaintenanceRange(start:string,end:string){const nights=maintenanceNights(start,end);return Number.isSafeInteger(nights)&&nights>=1&&nights<=366}
export function validMaintenanceReason(reason:unknown):reason is string{return typeof reason==='string'&&reason===reason.trim()&&reason.length>=4&&reason.length<=500&&!Array.from(reason).some(c=>c.charCodeAt(0)<32||c.charCodeAt(0)===127)}
export function validPendingMaintenance(value:unknown,scope:Scope):value is PendingMaintenance{
 if(!object(value)||!exactKeys(value,['actor','tenant','property','review','action','command'])||value.actor!==scope.actor||value.tenant!==scope.tenant||value.property!==scope.property||!uuid(value.actor)||!uuid(value.tenant)||!uuid(value.property)||!object(value.review)||!object(value.command))return false;
 const r=value.review,p=value.command;if(!exactKeys(r,['room_id','room_label','scheduled_start','scheduled_end'])||!uuid(r.room_id)||typeof r.room_label!=='string'||!r.room_label.trim()||!validMaintenanceRange(String(r.scheduled_start),String(r.scheduled_end))||!uuid(p.p_request)||!version(p.p_expected_room_version)||!validMaintenanceDate(p.p_expected_business_date)||!validMaintenanceReason(p.p_reason))return false;
 if(value.action==='create_room_closure')return exactKeys(p,['p_request','p_expected_room_version','p_expected_business_date','p_reason','p_room','p_start','p_end'])&&p.p_room===r.room_id&&p.p_start===r.scheduled_start&&p.p_end===r.scheduled_end&&typeof p.p_start==='string'&&typeof p.p_end==='string'&&p.p_start>=p.p_expected_business_date&&p.p_end<=addMaintenanceDays(p.p_expected_business_date,366);
 return value.action==='release_room_closure'&&exactKeys(p,['p_request','p_expected_room_version','p_expected_business_date','p_reason','p_closure'])&&uuid(p.p_closure);
}
function validClosure(value:unknown):value is RoomClosure{if(!object(value))return false;return uuid(value.id)&&uuid(value.room_id)&&uuid(value.room_type_id)&&typeof value.room_label==='string'&&!!value.room_label.trim()&&version(value.room_state_version)&&typeof value.scheduled_start==='string'&&typeof value.scheduled_end==='string'&&validMaintenanceRange(value.scheduled_start,value.scheduled_end)&&validMaintenanceDate(value.effective_end)&&value.effective_end>=value.scheduled_start&&value.effective_end<=value.scheduled_end&&typeof value.reason==='string'&&timestamp(value.created_at)&&uuid(value.created_by)&&typeof value.created_time_zone==='string'&&!!value.created_time_zone&&(value.released_at===null||timestamp(value.released_at))&&(value.released_by===null||uuid(value.released_by))&&(value.release_reason===null||typeof value.release_reason==='string')&&['scheduled','active','ended','released'].includes(String(value.status))&&(value.occupied_reservation_id===null||uuid(value.occupied_reservation_id))&&typeof value.occupancy_conflict==='boolean'}
export function validateMaintenanceData(value:MaintenanceData,property:string,start:string,end:string){
 if(!value||value.property_id!==property||!validMaintenanceDate(value.business_date)||typeof value.time_zone!=='string'||!value.time_zone||!['owner','manager','staff'].includes(value.role)||value.can_manage!==['owner','manager'].includes(value.role)||!timestamp(value.generated_at)||value.period?.start!==start||value.period?.end!==end||value.period?.end_exclusive!==true||!Array.isArray(value.closures)||value.closures.length>1000||!value.closures.every(validClosure)||new Set(value.closures.map(c=>c.id)).size!==value.closures.length||!Array.isArray(value.inventory)||value.inventory.length>10000)throw Error('Maintenance data is incomplete or does not match this property and date range. Refresh before reviewing a closure.');
 const inventoryKeys=new Set<string>();for(const row of value.inventory){const key=row.stay_date+':'+row.room_type_id,effective=row.configured_units===null?null:Math.min(row.configured_units,row.physical_units-row.closed_units);if(inventoryKeys.has(key)||!validMaintenanceDate(row.stay_date)||row.stay_date<start||row.stay_date>=end||!uuid(row.room_type_id)||typeof row.room_type_name!=='string'||![row.physical_units,row.closed_units,row.reserved_units].every(count)||![row.configured_units,row.effective_units,row.available_units,row.shortfall_units].every(n=>n===null||count(n))||row.closed_units>row.physical_units||row.effective_units!==effective||row.available_units!==(effective===null?null:Math.max(effective-row.reserved_units,0))||row.shortfall_units!==(effective===null?null:Math.max(row.reserved_units-effective,0)))throw Error('Maintenance inventory contains an invalid count, date or capacity reconciliation. Refresh before continuing.');inventoryKeys.add(key);}
}
export function validateMaintenanceStatus(value:unknown):asserts value is MaintenanceStatus{if(!object(value)||typeof value.found!=='boolean'||(!value.found&&!exactKeys(value,['found'])))throw Error('The maintenance receipt lookup returned an incomplete result. Keep the saved request and check again.')}
export function validateMaintenanceReceipt(status:MaintenanceStatus,pending:PendingMaintenance){
 const p=pending.command,r=status.result,c=r?.closure,expectedEnd=pending.action==='create_room_closure'?pending.command.p_end:[pending.review.scheduled_start,[pending.review.scheduled_end,p.p_expected_business_date].sort()[0]].sort()[1];
 if(!status.found||status.action!==pending.action||!r||r.action!==pending.action||r.tenant_id!==pending.tenant||r.property_id!==pending.property||r.request_id!==p.p_request||r.room_id!==pending.review.room_id||!version(r.room_state_version)||r.room_state_version!==p.p_expected_room_version+1||r.business_date!==p.p_expected_business_date||r.housekeeping_changed!==false||r.financial_changed!==false||r.configured_capacity_changed!==false||typeof r.replayed!=='boolean'||!validClosure(c)||c.room_id!==pending.review.room_id||c.room_label!==pending.review.room_label||c.room_state_version!==r.room_state_version||c.scheduled_start!==pending.review.scheduled_start||c.scheduled_end!==pending.review.scheduled_end||c.effective_end!==expectedEnd||(pending.action==='create_room_closure'?(c.reason!==p.p_reason||c.created_by!==pending.actor||c.released_at!==null||c.released_by!==null||c.release_reason!==null):(c.id!==pending.command.p_closure||c.release_reason!==p.p_reason||c.released_by!==pending.actor||c.released_at===null)))throw Error('The maintenance receipt does not match this saved request. Keep the request and reconcile this room before continuing.');
 return r;
}
export function roomMaintenanceOverlaps(room:MaintenanceRoom,start:string,end:string|null){return room.maintenance_intervals?.some(interval=>(end===null||interval.start<end)&&interval.end>start)??false}
export function maintenanceAssignmentInterval(businessDate:string,departure:string|null,overdue=false):{start:string;end:string|null}{if(!validMaintenanceDate(businessDate))throw Error('The current property date is required for room availability.');if(overdue||departure===null||!validMaintenanceDate(departure)||departure<businessDate)return {start:businessDate,end:null};return {start:businessDate,end:departure===businessDate?addMaintenanceDays(businessDate,1):departure}}
export function maintenanceExportRows(data:MaintenanceData,kind:'closures'|'inventory',propertyName:string):ReportCell[][]{
 const metadata:ReportCell[][]=[['iRatePilot PMS',kind==='closures'?'Room maintenance closures':'Room maintenance inventory'],['Property',propertyName],['Property ID',data.property_id],['Time zone',data.time_zone],['Period start',data.period.start],['Period end (exclusive)',data.period.end],['Property business date',data.business_date],['Generated at',data.generated_at],['Closure date basis','Original scheduled interval overlap; effective end records early release. End dates are excluded.'],['Inventory basis','Current configured selling ceiling and current physical rooms, reduced by effective dated closures. Missing configured capacity stays unavailable. Historical room assignments are not reconstructed.'],['Readiness','Scheduled expiry and early release restore dated availability but do not certify repair or housekeeping readiness.'],[]];
 return kind==='closures'?[...metadata,['Closure ID','Room ID','Room label','Room type ID','Room revision','Scheduled start','Scheduled end (exclusive)','Effective end (exclusive)','Status','Creation reason','Created at','Created by','Creation time zone','Released at','Released by','Release reason','Occupied reservation ID','Occupancy conflict'],...data.closures.map(c=>[c.id,c.room_id,c.room_label,c.room_type_id,c.room_state_version,c.scheduled_start,c.scheduled_end,c.effective_end,c.status,c.reason,c.created_at,c.created_by,c.created_time_zone,c.released_at,c.released_by,c.release_reason,c.occupied_reservation_id,c.occupancy_conflict?'Yes':'No'])]:[...metadata,['Stay night','Room type ID','Room type','Configured units','Physical units','Closed units','Effective units','Reserved units','Available units','Shortfall units'],...data.inventory.map(row=>[row.stay_date,row.room_type_id,row.room_type_name,row.configured_units,row.physical_units,row.closed_units,row.effective_units,row.reserved_units,row.available_units,row.shortfall_units])];
}
